import { useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { Link, useNavigate } from 'react-router-dom';
import { authApi } from '@/api/auth.api';
import styles from './auth.module.css';

const schema = z.object({
  phoneE164: z
    .string()
    .regex(/^\+252[1-9][0-9]{7,8}$/, 'Enter a valid Somali number, e.g. +252612345678'),
});

type FormData = z.infer<typeof schema>;

export function ForgotPasswordPage(): JSX.Element {
  const navigate = useNavigate();
  const [sent, setSent] = useState(false);
  const [phone, setPhone] = useState('');

  const {
    register,
    handleSubmit,
    formState: { errors, isSubmitting },
  } = useForm<FormData>({ resolver: zodResolver(schema) });

  const onSubmit = async (data: FormData) => {
    try {
      await authApi.forgotPassword(data);
    } catch {
      // Anti-enumeration: always show "sent" to prevent phone discovery
    } finally {
      setPhone(data.phoneE164);
      setSent(true);
    }
  };

  if (sent) {
    return (
      <div className={styles.page}>
        <div className={styles.card}>
          <div className={styles.brand}>
            <span className={styles.brandMark}>SL</span>
          </div>
          <h1 className={styles.title}>Check Your Phone</h1>
          <p className={styles.subtitle}>
            If that number is registered, a reset code has been sent.
          </p>
          <button
            className={styles.submitBtn}
            onClick={() => navigate(`/reset-password?phone=${encodeURIComponent(phone)}`)}
          >
            Enter Code
          </button>
          <div className={styles.footer}>
            <Link to="/login" className={styles.link}>
              Back to Login
            </Link>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className={styles.page}>
      <div className={styles.card}>
        <div className={styles.brand}>
          <span className={styles.brandMark}>SL</span>
        </div>
        <h1 className={styles.title}>Forgot Password</h1>
        <p className={styles.subtitle}>Enter your phone number to receive a reset code</p>

        <form onSubmit={handleSubmit(onSubmit)} noValidate>
          <div className={styles.field}>
            <label className={styles.label} htmlFor="phoneE164">
              Phone Number
            </label>
            <input
              id="phoneE164"
              className={`${styles.input}${errors.phoneE164 ? ` ${styles.inputError}` : ''}`}
              type="tel"
              autoComplete="tel"
              placeholder="+252612345678"
              {...register('phoneE164')}
            />
            {errors.phoneE164 && (
              <p className={styles.fieldError} role="alert">
                {errors.phoneE164.message}
              </p>
            )}
          </div>

          <button type="submit" className={styles.submitBtn} disabled={isSubmitting}>
            {isSubmitting ? 'Sending…' : 'Send Code'}
          </button>
        </form>

        <div className={styles.footer}>
          <Link to="/login" className={styles.link}>
            Back to Login
          </Link>
        </div>
      </div>
    </div>
  );
}

export default ForgotPasswordPage;
